// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t1) public {
        t1 = bound(t1, 1, type(uint256).max / 2);
        address actor = address(0xA11CE);
        vm.deal(actor, 100 ether);

        // first call at time t1 succeeds on both versions
        vm.warp(t1);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // general rule: for any timestamp t2 <= t1 + 1 the next call must revert,
        // because the reference stores pastBlockTime = t1 + 1.
        // The mutant stores t1, so a call at t1 + 1 wrongly succeeds.
        vm.warp(t1 + 1);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2, "second call within one second must revert");
    }
}
